<script module lang="ts">
/**
 * A Button preset whose face is an Avatar (`design/components/avatar-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  agentMember,
  agentPress,
  chainHandlers,
  joinSlot,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/avatar-button.module.css'
import Avatar from '../structure/Avatar.svelte'

export interface AvatarButtonProps {
  /**
   * Marks the button as the current location with `aria-current="page"`, as Button's `current`
   * does.
   */
  current?: boolean
  disabled?: boolean
  /**
   * The accessible name of the action, such as "Account menu". It is required and it is not the
   * person's name: a face says who, and a button says what a press does.
   */
  label: string
  /**
   * The action has started and not finished. Keeps focus and name, hides the face behind the
   * spinner, and ignores presses.
   */
  loading?: boolean
  /**
   * Avatar's `name`: the initials, and the `user` glyph when it is empty. Never the accessible
   * name.
   */
  name: string
  onClick?: (event: MouseEvent) => void
  /**
   * Makes the button a toggle, as Button's `pressed` does: `aria-pressed` mirrors it and
   * `data-state="on|off"` exposes it to CSS. Omitted, the button is not a toggle.
   */
  pressed?: boolean
  /**
   * The face's size, which is Avatar's. The box around it is never smaller than the size's
   * control height.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * Avatar's `src`: the image. A URL that fails to load leaves the initials.
   */
  src?: string
}
</script>

<script lang="ts">
let {
  current = false,
  disabled = false,
  label: labelOwn,
  loading = false,
  name,
  onClick: onClickOwn,
  pressed,
  size = 'md',
  src,
}: AvatarButtonProps = $props()
const joined = joinSlot(undefined, () => ({
  disabled: disabled,
  label: labelOwn,
  name: name,
  size: size,
}))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const onClick = $derived(chainHandlers(onClickOwn, joined.passed['onClick']))
let control = $state<HTMLElement | null>(null)
const dataState = $derived(
  loading ? 'loading' : pressed === undefined ? undefined : pressed ? 'on' : 'off',
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'AvatarButton',
    element: () => control,
    state: () => ({ disabled: disabled, loading: loading }),
    actions: { press: () => agentPress(control) },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<button
    bind:this={control}
    class={styles.button}
    type="button"
    {disabled}
    aria-label={label}
    aria-busy={loading ? true : undefined}
    aria-current={current ? 'page' : undefined}
    aria-pressed={pressed}
    data-variant="ghost"
    data-tone="neutral"
    data-size={size}
    data-state={dataState}
    data-disabled={(disabled) ? '' : undefined}
    data-member="avatar-button"
    onclick={(event) => { if (!loading) onClick?.(event) }}
    ><span class={styles.face}><Avatar {name} {src} {size} /></span
    >{#if loading}<span class={styles.spinner}><Icon name="loading" {size} /></span>{/if
  }</button
>{/if
}{@render joined.end?.()}
